package com.projectsale.api.catalog.entity;
import com.projectsale.api.user.entity.EntityStatus; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="products") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="public_id",nullable=false,unique=true,insertable=false,updatable=false) private UUID publicId; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id") private Category category; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="brand_id") private Brand brand; @Column(nullable=false,length=200) private String name; @Column(nullable=false,unique=true,length=220) private String slug; private String description; @Column(name="min_price") private BigDecimal minPrice; @Column(name="thumbnail_url") private String thumbnailUrl; @Column(name="rating_avg") private BigDecimal ratingAvg; @Column(name="review_count",nullable=false) private int reviewCount; @Column(name="warranty_months") private Integer warrantyMonths; @Column(name="meta_title") private String metaTitle; @Column(name="meta_description") private String metaDescription; @Column(name="og_image") private String ogImage; private String gender; @Column(name="has_lens",nullable=false) private boolean hasLens; @JdbcTypeCode(SqlTypes.ARRAY) @Column(name="face_tags",columnDefinition="varchar(32)[]",nullable=false) private String[] faceTags; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="entity_status") private EntityStatus status; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; @Column(name="deleted_at") private Instant deletedAt; @OneToMany(mappedBy="product",fetch=FetchType.LAZY) @OrderBy("sortOrder asc") private List<ProductImage> images=new ArrayList<>(); @OneToMany(mappedBy="product",fetch=FetchType.LAZY) private List<ProductVariant> variants=new ArrayList<>(); public boolean visible(){return status==EntityStatus.ACTIVE&&deletedAt==null;} }
